MagickBooleanType ReadDXT5Image(Image *image, DDSInfo *dds_info, ExceptionInfo *exception) {
  register PixelRun *pixels = (PixelRun *) image->pixels;
  const size_t *quantum_map = image->quantum_map;
  unsigned int x, y, q, alpha0, alpha1;
  unsigned short color0, color1;
  unsigned char alpha[8], color[16];
  MagickBooleanType status = MagickTrue;
  size_t i, j;

  for (y = 0; y < (unsigned int) image->rows; y += 4) {
    for (x = 0; x < (unsigned int) image->columns; x += 4) {
      for (i = 0; i < 12; i++) {
        for (j = 0; j < 8; j++) {
          if ((i < 6) && (j < 2))
            alpha[j] = (unsigned char) (GetLSBByte(dds_info->alpha_data[i]));
          else
            alpha[j] = 0;
        }
        for (j = 0; j < 2; j++) {
          if ((i < 6) && (j < 2))
            color[j] = (unsigned char) (GetLSBByte(dds_info->color_data[i]));
          else
            color[j] = 0;
        }
        alpha0 = (unsigned int) alpha[0];
        alpha1 = (unsigned int) alpha[1];
        color0 = (unsigned short) (color[0] | (color[1] << 8));
        color1 = (unsigned short) (color[2] | (color[3] << 8));
        for (q = 0; q < 4; q++) {
          if (q < 2)
            pixels[(y + q) * image->columns + x + i] = (PixelRun) (color0 | (alpha0 << 16));
          else
            pixels[(y + q) * image->columns + x + i] = (PixelRun) (color1 | (alpha1 << 16));
        }
      }
    }
  }

  return status;
}

