    size_t block_height = (image->rows + 3) / 4;
    size_t num_blocks = block_width * block_height;
    Quantum *pixels;
    unsigned char *dxt5_data = dds_info->data;
    size_t alpha_index = 0;
    size_t color_index = 128;
    size_t y, x, block_y, block_x;
    unsigned short alpha0, alpha1;
    unsigned short color0, color1;
    unsigned int alpha_values[6];
    unsigned char alpha_code;
    unsigned short color_code;
    Quantum *pixel;

    pixels = (Quantum *) AcquireQuantumMemory(image->columns * image->rows, sizeof(Quantum) * 4);
    if (pixels == (Quantum *) NULL) {
        ThrowException(exception, ResourceLimitError, "MemoryAllocationFailed", "ReadDXT5Image");
        return MagickFalse;
    }

    for (block_y = 0; block_y < block_height; block_y++) {
        for (block_x = 0; block_x < block_width; block_x++) {
            alpha0 = *dxt5_data++;
            alpha0 |= (*dxt5_data++) << 8;
            alpha1 = *dxt5_data++;
            alpha1 |= (*dxt5_data++) << 8;

            if (alpha0 > alpha1) {
                alpha_values[0] = alpha0;
                alpha_values[1] = alpha1;
                for (size_t i = 2; i < 6; i++) {
                    alpha_values[i] = (6 * alpha0 - alpha1 * (6 - i)) / 5;
                }
            }
            else {
                alpha_values[0] = alpha0;
                alpha_values[1] = alpha1;
                for (size_t i = 2; i < 6; i++) {
                    alpha_values[i] = (alpha0 * (6 - i) + alpha1 * i) / 5;
                }
            }

            for (y = 0; y < 4; y++) {
                for (x = 0; x < 4; x++) {
                    alpha_code = *dxt5_data++;
                    alpha_values[0] = (alpha_values[alpha_code >> 4] << 8) & 0xff00;
                    alpha_values[1] = (alpha_values[alpha_code & 0x0f] & 0x00ff);
                    pixel = pixels + (block_y * 4 + y) * image->columns + (block_x * 4 + x);
                    pixel[0] = (Quantum) alpha_values[0];
                    pixel[1] = (Quantum) alpha_values[1];
                }
            }

            color0 = *dxt5_data++;
            color0 |= (*dxt5_data++) << 8;
            color1 = *dxt5_data++;
            color1 |= (*dxt5_data++) << 8;

            for (y = 0; y < 4; y++) {
                for (x = 0; x < 4; x++) {
                    color_code = *dxt5_data++;
                    pixel = pixels + (block_y * 4 + y) * image->columns + (block_x * 4 + x);
                    pixel[2] = (Quantum) (((color0 >> 11) & 0x1f) * 8);
                    pixel[3] = (Quantum) (((color0 >> 5) & 0x3f) * 4);
                    pixel[4] = (Quantum) (((color0 >> 0) & 0x1f) * 8);
                }
            }
        }
    }

    SyncImagePixels(image);
    RelinquishMagickMemory(pixels);

    return MagickTrue;
}

