  if (image->depth != 8)
  {
    (void) ThrowMagickException(exception, GetMagickModule(), ImageError, "InvalidDepth", "`depth' must be 8 for DXT5 images");
    return MagickFalse;
  }

  block_width = (image->columns + 3) / 4;
  block_height = (image->rows + 3) / 4;

  if (image->storage_class != PseudoClass)
  {
    (void) SetImageStorageClass(image, PseudoClass, exception);
    if (AllocateImageColormap(image, 256, exception) == MagickFalse)
      return MagickFalse;
  }

  for (y = 0; y < block_height; y++)
  {
    for (x = 0; x < block_width; x++)
    {
      unsigned int color0, color1;
      unsigned int color_data[8];
      unsigned int alpha0, alpha1;
      unsigned int alpha_table[16];
      unsigned int alpha_index[16];
      unsigned int alpha_index_offset = 0;
      size_t i;

      for (i = 0; i < 16; i++)
      {
        alpha_index[i] = (dxt5_data[0] >> (4 * (15 - i))) & 0x0F;
        alpha_index_offset += 4;
        if (alpha_index_offset >= 8)
          break;
      }

      alpha0 = *(unsigned int *)&dxt5_data[8];
      alpha1 = *(unsigned int *)&dxt5_data[12];

      for (i = 0; i < 16; i++)
      {
        if (alpha_index[i] <= 4)
          alpha_data[i] = (alpha0 * (4 - alpha_index[i]) + alpha1 * alpha_index[i]) / 4;
        else if (alpha_index[i] <= 12)
          alpha_data[i] = (alpha1 * (12 - alpha_index[i]) + alpha0 * (alpha_index[i] - 4)) / 8;
        else
          alpha_data[i] = alpha1;
      }

      dxt5_data += 16;
    }
  }

  return MagickTrue;
}

MagickBooleanType ReadDXT5Image(Image *image, DDSInfo *dds_info, ExceptionInfo *exception) {
  register ssize_t x, y;
  size_t row;
  unsigned int alpha1, alpha2;
  unsigned short color1, color2;
  unsigned char *block;
  ssize_t block_index;
  MagickBooleanType status = MagickTrue;

  for (y = 0; y < (ssize_t) dds_info->height; y += 4) {
    for (x = 0; x < (ssize_t) dds_info->width; x += 4) {
      block = (unsigned char *) AcquireMemory(16);
      if (block == (unsigned char *) NULL) {
        ThrowException(exception, ResourceLimitError, UnableToAcquireMemory, "DXT5 block");
        return MagickFalse;
      }
      // Read the DXT5 block data
      // ... (code to read compressed block data)

      // Extract alpha values
      alpha1 = ((block[1] & 0x0F) << 4) | (block[0] >> 4);
      alpha2 = ((block[0] & 0x0F) << 4) | (block[1] >> 4);

      // Extract color values
      color1 = (block[4] << 8) | block[5];
      color2 = (block[2] << 8) | block[3];

      // Decode the DXT5 block into pixels
      for (row = 0; row < 4; row++) {
        register ssize_t index = 0;
        register unsigned char *pixel_row = block + 8 + (row * 2);
        while (index < 8) {
          unsigned char alpha = alpha1;
          unsigned short color = color1;
          switch (pixel_row[index >> 3]) {
            case 0:
              alpha = alpha1;
              color = color1;
              break;
            case 1:
              alpha = alpha2;
              color = color2;
              break;
            case 2:
              alpha = (3 * alpha1 + alpha2) / 4;
              color = ((3 * color1 + color2) >> 2);
              break;
            case 3:
              alpha = (alpha1 + 3 * alpha2) / 4;
              color = ((color1 + 3 * color2) >> 2);
              break;
            case 4:
              alpha = (alpha1 + alpha2) / 2;
              color = ((color1 + color2) >> 1);
              break;
            case 5:
              alpha = (alpha1 + 3 * alpha2) / 4;
              color = ((color1 + 3 * color2) >> 2);
              break;
            case 6:
              alpha = (3 * alpha1 + alpha2) / 4;
              color = ((3 * color1 + color2) >> 2);
              break;
            case 7:
              alpha = alpha2;
              color = color2;
              break;
          }

          // Set the decoded pixel in the image
          PixelPacket *pixel = AcquireImagePixelCachePixel(image, x + (index & 0x0F), y + row, exception);
          pixel->red = (Quantum) (color >> 8);
          pixel->green = (Quantum) ((color >> 4) & 0x0F);
          pixel->blue = (Quantum) (color & 0x0F);
          pixel->opacity = (Quantum) alpha;

          index += 2;
        }
      }

      // Free the DXT5 block memory
      RelinquishMemory(block);
    }
  }

  return status;
}
